const linhas = $input.all().map((i) => i.json);
if (linhas.length === 0) {
  return [];
}

const cab = linhas[0];
const fmtBRL = (v) => (Number(v) || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const cartaz = linhas.filter((l) => l.braco === 'desconto');
const controle = linhas.filter((l) => l.braco === 'controle');

const out = [
  `📋 *Proposta de campanha — ${cab.campanha}*`,
  `Período: ${cab.inicio} a ${cab.fim}`,
  '',
  `*${cartaz.length} produtos pro cartaz:*`,
  '',
];

cartaz.forEach((l, i) => {
  out.push(`${i + 1}. ${l.produto}`);
  out.push(`   ${fmtBRL(l.preco_promocional)} (-${l.desconto_pct}%) · estoque ${l.estoque_atual}`);
});

if (controle.length) {
  out.push('');
  out.push(`🔒 *${controle.length} em grupo de controle* — não imprimir, não exportar. Servem pra medir se o cartaz fez diferença no fim do mês.`);
}

out.push('');
out.push('Abra a aba *Campanhas* no app pra revisar, ajustar preço ou excluir item. O preço só vale no caixa depois que você exportar o .txt e importar no Trier.');

return [{ json: { mensagem: out.join('\n') } }];
